// ===== app.js part 1 =====

const $=s=>document.querySelector(s), app=$('#app');
let state={view:'home',importId:null,quizId:null,editIndex:0,quizMode:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200);}
function nav(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));}
async function go(v){state.view=v;state.quizMode=null;nav();await render();}
function stepper(n){const names=['Choose PDF','Extract TXT','Inspect/Edit TXT','Approve TXT','Detect MCQs','Review/Correct','Approve','Generate JSON','Add to Library'];return `<div class="steps">${names.map((x,i)=>`<div class="step ${i+1<n?'done':''} ${i+1===n?'current':''}">STEP ${i+1}<br>${x}</div>`).join('')}</div>`}
function downloadJSON(obj,name){makeDownload(JSON.stringify(obj,null,2),name.replace(/\s+/g,'_')+'.json');}

async function render(){app.innerHTML='';nav();if(state.view==='home')return home();if(state.view==='import')return importView();if(state.view==='library')return library();if(state.view==='daily')return daily();if(state.view==='wrong')return wrong();if(state.view==='review')return review();}
async function home(){const qs=await all('quizzes');const prog=await all('progress');const wrong=prog.filter(p=>p.wrong).length;const due=prog.filter(p=>isDue(p)).length;app.innerHTML=`<section class="card"><h1>Local MCQ Study</h1><p class="muted">Your books stay on this device. The app refuses to turn a PDF directly into a quiz, because apparently humans are still required for quality control.</p></section><div class="grid"><div class="card"><div class="stat">${qs.length}</div><div>Quiz sources</div></div><div class="card"><div class="stat">${wrong}</div><div>Wrong-answer items</div></div><div class="card"><div class="stat">${due}</div><div>Due reviews</div></div></div><section class="card"><h2>Backup</h2><div class="row"><button id="export">Export all app data</button><label class="secondary" style="padding:10px 14px;border-radius:10px;background:#e7edf5;color:#152238;cursor:pointer">Import backup <input id="backup" type="file" accept=".json,application/json" hidden></label></div><p class="muted small">Backups include imports, source TXT records, quizzes, progress and daily papers.</p></section><section class="card"><h2>Pipeline</h2><p>PDF → TXT → <b>you inspect it</b> → approve → MCQ detection → <b>you approve/fix questions</b> → JSON → <b>you add to Library</b>.</p><button id="start">Start an import</button></section>`;
 $('#export').onclick=async()=>downloadJSON(await exportAll(),'mcq-study-backup');$('#backup').onchange=async e=>{try{const txt=await e.target.files[0].text();await importAll(JSON.parse(txt));toast('Backup imported');render();}catch(err){toast('Backup import failed: '+err.message)}};$('#start').onclick=()=>go('import');}

async function importView(){
 const imp=state.importId?await get('imports',state.importId):null;
 if(!imp){app.innerHTML=`${stepper(1)}<section class="card"><h1>Import</h1><div class="drop"><b>STEP 1 · Choose a source</b><p class="muted">PDF starts the protected extraction pipeline. TXT can be inspected directly. JSON can be imported as an already-approved quiz.</p><input id="file" type="file" accept=".pdf,.txt,.json,application/pdf,text/plain,application/json"></div></section>`;$('#file').onchange=wrappedSource;return;}
 if(imp.stage==='EXTRACTED' || imp.stage==='OCR')return txtStage(imp);
 if(imp.stage==='TXT_APPROVED')return detectStage(imp);
 if(imp.stage==='PARSED')return reviewStage(imp);
 if(imp.stage==='APPROVED')return jsonStage(imp);
 if(imp.stage==='ADDED')return addedStage(imp);
}
async function handleSource(e){const f=e.target.files[0];if(!f)return;const id='imp_'+Date.now().toString(36);if(f.name.toLowerCase().endsWith('.txt')){const txt=await f.text();const imp={id,sourceFilename:f.name,sourceName:f.name.replace(/\.[^.]+$/,''),stage:'EXTRACTED',txt,pages:[],createdAt:new Date().toISOString(),diagnostics:{pagesProcessed:0,pagesWithText:0,pagesOCRd:0}};await put('imports',imp);state.importId=id;render();return;}if(f.name.toLowerCase().endsWith('.json')){try{const data=JSON.parse(await f.text());let qs=data.questions||data.quiz?.questions;if(!Array.isArray(qs))throw Error('JSON does not contain a questions array');qs=qs.map((q,i)=>({...q,id:q.id||('q_import_'+Date.now().toString(36)+'_'+i.toString(36))}));const imp={id,sourceFilename:data.sourceFilename||f.name,sourceName:data.quizName||data.sourceName||f.name,stage:'APPROVED',approvedQuestions:qs,txt:data.sourceTxt||'',createdAt:new Date().toISOString(),diagnostics:{}};await put('imports',imp);state.importId=id;render();return;}catch(err){toast('JSON import failed: '+err.message);return;}}
 if(!f.name.toLowerCase().endsWith('.pdf'))return toast('Choose PDF, TXT or JSON');
 state.importId=id;const imp={id,sourceFilename:f.name,sourceName:f.name.replace(/\.[^.]+$/,''),stage:'EXTRACTING',createdAt:new Date().toISOString(),diagnostics:{pagesProcessed:0,pagesWithText:0,pagesOCRd:0}};await put('imports',imp);render();
 try{const r=await extractPDF(f,{onProgress:(n,total)=>{imp.diagnostics.pagesProcessed=n;imp.diagnostics.totalPages=total;put('imports',imp);},onPage:p=>{imp.pages=imp.pages||[];imp.pages.push(p);}});imp.pages=r.pages;imp.diagnostics={pagesProcessed:r.pageCount,totalPages:r.pageCount,pagesWithText:r.textPages,pagesOCRd:r.ocrPages};imp.txt=toTXT(r);imp.stage='EXTRACTED';await put('imports',imp);render();}catch(err){imp.stage='EXTRACTED';imp.error=err.message;imp.txt='[PDF extraction failed]\n'+err.stack;await put('imports',imp);render();}}

async function txtStage(imp){const flagged=(imp.pages||[]).filter(p=>p.method==='ocr-needed');app.innerHTML=`${stepper(3)}<section class="card"><h1>Inspect / Edit TXT</h1><div class="notice"><b>Source record:</b> ${esc(imp.sourceFilename)}<br>Pages processed: ${imp.diagnostics?.pagesProcessed||0} · pages with text: ${imp.diagnostics?.pagesWithText||0} · pages needing OCR: ${flagged.length}<br>${flagged.length?'Pages marked OCR REQUIRED are still present. They have not been silently discarded.':''}</div><div class="toolbar"><input id="txtSearch" class="search" placeholder="Search within TXT"><div class="row"><button id="saveTxt">Save TXT</button><button id="downloadTxt" class="secondary">Download TXT</button>${flagged.length?'<button id="ocrAll">OCR all flagged pages</button>':''}</div></div><textarea id="txt">${esc(imp.txt||'')}</textarea><div id="ocrStatus"></div><div class="row"><button id="approveTxt">Approve TXT and continue to MCQ detection</button></div></section>`;
 $('#saveTxt').onclick=async()=>{imp.txt=$('#txt').value;imp.stage='EXTRACTED';await put('imports',imp);toast('TXT saved');};$('#downloadTxt').onclick=()=>makeDownload($('#txt').value,imp.sourceFilename.replace(/\.pdf$/i,'')+'.txt');$('#txtSearch').oninput=e=>{const v=e.target.value;if(v){const text=$('#txt').value;const pos=text.toLowerCase().indexOf(v.toLowerCase());toast(pos>=0?`Found at character ${pos+1}`:'Not found')}};$('#approveTxt').onclick=async()=>{imp.txt=$('#txt').value;imp.txtApprovedAt=new Date().toISOString();imp.stage='TXT_APPROVED';await put('imports',imp);render();};if($('#ocrAll'))$('#ocrAll').onclick=async()=>{for(const p of flagged){$('#ocrStatus').textContent=`OCR page ${p.page} of ${imp.diagnostics.totalPages}…`;try{p.text=await ocrPage(window.__lastPDFFile||null,p.page,{onProgress:x=>{}})}catch(e){p.text='[OCR FAILED: '+e.message+']';p.ocrError=e.message}p.method='ocr';imp.diagnostics.pagesOCRd=(imp.diagnostics.pagesOCRd||0)+1;imp.txt=toTXT({pages:imp.pages});await put('imports',imp);$('#txt').value=imp.txt;}$('#ocrStatus').textContent='OCR pass complete. Inspect the TXT again before approval.';};
 // File objects are not persistent; for OCR after page extraction we need the selected PDF. Keep it only in memory during this browser session.
 if(window.__lastPDFFile==null && imp.sourceFilename.toLowerCase().endsWith('.pdf')){$('#ocrAll').disabled=true;if($('#ocrStatus'))$('#ocrStatus').textContent='OCR needs the selected PDF still available in this browser session. Re-select the same PDF in this import if needed.';}
}
